head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};

scwin.submission1_done = function(e) {
	var totrowcnt = dataList3.getRowCount();
	pageList3.setCount(Number(totrowcnt) / gridRowCount);
};

scwin.pageList3_onchange = function(current, before) {
	log = "current = " + current + ", before = " + before;
};

scwin.pageList3_oninputblur = function(value) {
	log1 = "value = " + value;
};

scwin.checkVal1 = function() {
	return scwin.__getObj('pageList3').getSelectedIndex() == 7;
};

scwin.checkVal2 = function() {
	return scwin.__getObj('pageList3').getCount() == 6;
};

scwin.checkVal3 = function() {
	return log == 'current = 5, before = 1';
};

scwin.checkVal4 = function() {
	return log1 == 'value = 5';
};

scwin.onpageload = function() {
	window.gridRowCount = 7;
	$w.executeSubmission("submission1");
};
